#: Nautilus bar aggregation -> the bridge's timeframe name, and the bar's
#: length in seconds. The seconds matter: **`ts_event` on a Nautilus bar is
#: the bar's close**, and MT5 stamps a bar with its open, so one has to be
#: converted into the other. Getting it backwards does not shift a series
#: feeding `statespace` - it silences it, because `observe_bar` refuses a bar
#: whose time is not strictly after the last one.
TIMEFRAMES: dict[str, tuple[str, float]] = {
    "1-MINUTE": ("M1", 60.0),
    "5-MINUTE": ("M5", 300.0),
    "15-MINUTE": ("M15", 900.0),
    "30-MINUTE": ("M30", 1800.0),
    "1-HOUR": ("H1", 3600.0),
    "4-HOUR": ("H4", 14400.0),
    "1-DAY": ("D1", 86400.0),
}


#: Where live quotes come from.
#:
#: - `poll`: ask for the current tick every `poll_seconds`. A **sample**: two
#:   ticks inside one interval arrive as the later of them.
#: - `ticks`: ask for every tick since the last one seen (`copy_ticks_range`).
#:   **Complete, not instant** - nothing is lost, and the latest arrives up to
#:   one interval late. Needs no change to the terminal.
#: - `push`: the transport hands over ticks as the terminal produces them
#:   (an Expert Advisor's `OnTick`, relayed by the bridge). Complete and
#:   immediate, and only available where the transport has a `stream`.
QUOTE_SOURCES: tuple[str, ...] = ("poll", "ticks", "push")


def _milliseconds(row: dict) -> int | None:
    """A tick's time in epoch milliseconds, whichever way the transport spelled it.

    rpyc returns MT5's own integers. The HTTP bridge runs the same rows through
    `pandas.to_datetime`, so `time_msc` arrives as an ISO string and `time` as
    one too - the same tick in two shapes. A naive string is UTC, which is how
    pandas produced it from an epoch.
    """
    for key, scale in (("time_msc", 1), ("time", 1000)):
        value = row.get(key)
        if value in (None, ""):
            continue
        if isinstance(value, datetime):
            value = value if value.tzinfo else value.replace(tzinfo=UTC)
            return int(value.timestamp() * 1000)
        if isinstance(value, str):
            try:
                parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
            except ValueError:
                continue
            parsed = parsed if parsed.tzinfo else parsed.replace(tzinfo=UTC)
            return int(parsed.timestamp() * 1000)
        try:
            return int(float(value) * scale)
        except (TypeError, ValueError):
            continue
    return None


class MT5DataClient(LiveMarketDataClient):
    """The read side of the venue."""

    def __init__(
        self,
        loop: asyncio.AbstractEventLoop,
        client_id: ClientId,
        venue: Venue,
        msgbus: Any,
        cache: Any,
        clock: Any,
        instrument_provider: MT5InstrumentProvider,
        config: MT5DataClientConfig,
    ) -> None:
        super().__init__(
            loop=loop,
            client_id=client_id,
            venue=venue,
            msgbus=msgbus,
            cache=cache,
            clock=clock,
            instrument_provider=instrument_provider,
            config=config,
        )
        self._cfg = config
        self._bridge = connect(config)
        self._pollers: dict[str, asyncio.Task] = {}
        #: The last bar time published per bar type, so a forming bar is not
        #: published twice. `prices` learned this the hard way: a notice per
        #: *touched* bar meant the bar in progress arrived on every sweep, and
        #: folding it each time both multiplied the observation count and fed a
        #: range that was still growing.
        self._last_bar: dict[str, int] = {}
        #: Per symbol, the newest tick time published and the `(bid, ask)`
        #: pairs already published *at that millisecond*. Several quote
        #: updates can share a millisecond, so time alone cannot de-duplicate:
        #: the pairs are what let an overlapping backfill or a replayed frame
        #: be recognised without dropping a genuine second tick.
        self._mark: dict[str, tuple[int, set[tuple[float, float]]]] = {}
        #: The last `seq` seen per symbol on a push stream, for gap detection.
        self._seq: dict[str, int] = {}
        #: How many ticks were refused as older than the watermark.
        self.stale_ticks = 0

    # ──── lifecycle ────
    async def _connect(self) -> None:
        try:
            await self._bridge.open()
            answered = await self._bridge.ping()
        except Exception as exc:
            # `from None`: the chained exception's text is the unscrubbed one,
            # and the framework logs the whole traceback.
            raise ConnectionError(self._scrub(exc)) from None
        if not answered:
            raise ConnectionError(f"the bridge at {self._scrub(self._cfg.base_url)} did not answer")
        self._check_quote_source()
        await self._instrument_provider.load_all_async()
        for instrument in self._instrument_provider.list_all():
            self._handle_data(instrument)
        self._log.info(f"loaded {len(self._instrument_provider.list_all())} instruments")

    def _scrub(self, value: Any) -> str:
        """Text safe to log: the configured API key and `api_key=` removed."""
        return redact(value, (getattr(self._cfg, "api_key", None),))

    @property
    def quote_source(self) -> str:
        return str(getattr(self._cfg, "quote_source", "poll") or "poll").lower()

    def _check_quote_source(self) -> None:
        """Refuse a source this transport cannot honour, rather than degrade.

        A `push` that quietly became a poll would report a complete stream and
        deliver a sampled one - the failure this option exists to end.
        """
        if self.quote_source not in QUOTE_SOURCES:
            raise ValueError(
                f"unknown quote_source {self.quote_source!r}: one of {', '.join(QUOTE_SOURCES)}"
            )
        if self.quote_source == "push" and not callable(getattr(self._bridge, "stream", None)):
            raise ConnectionError(
                f"quote_source='push' needs a transport with a tick stream, and "
                f"{type(self._bridge).__name__} has none - use 'ticks' for a complete feed "
                f"without one"
            )

    async def _disconnect(self) -> None:
        for task in list(self._pollers.values()):
            task.cancel()
        for task in list(self._pollers.values()):
            with contextlib.suppress(asyncio.CancelledError, Exception):
                await task
        self._pollers.clear()
        await self._bridge.close()

    # ──── subscriptions ────
    async def _subscribe_quote_ticks(self, command: Any) -> None:
        key = f"quotes:{command.instrument_id}"
        if key not in self._pollers:
            run = {
                "poll": self._poll_quotes,
                "ticks": self._pull_ticks,
                "push": self._stream_quotes,
            }[self.quote_source]
            self._pollers[key] = self.create_task(run(command.instrument_id))

    async def _unsubscribe_quote_ticks(self, command: Any) -> None:
        self._stop(f"quotes:{command.instrument_id}")

    async def _subscribe_bars(self, command: Any) -> None:
        key = f"bars:{command.bar_type}"
        if key not in self._pollers:
            self._pollers[key] = self.create_task(self._poll_bars(command.bar_type))

    async def _unsubscribe_bars(self, command: Any) -> None:
        self._stop(f"bars:{command.bar_type}")

    def _stop(self, key: str) -> None:
        task = self._pollers.pop(key, None)
        if task is not None:
            task.cancel()

    # ──── polling ────
    async def _poll_quotes(self, instrument_id: Any) -> None:
        symbol = instrument_id.symbol.value
        instrument = self._instrument_provider.find(instrument_id)
        last: tuple[float, float] | None = None
        while True:
            try:
                info = await self._bridge.symbol_info(symbol)
                bid, ask = float(info.get("bid") or 0.0), float(info.get("ask") or 0.0)
                if bid > 0 and ask > 0 and (bid, ask) != last:
                    last = (bid, ask)
                    now = self._clock.timestamp_ns()
                    self._handle_data(
                        QuoteTick(
                            instrument_id=instrument_id,
                            bid_price=Price(bid, instrument.price_precision),
                            ask_price=Price(ask, instrument.price_precision),
                            bid_size=Quantity(1, 0),
                            ask_size=Quantity(1, 0),
                            ts_event=now,
                            ts_init=now,
                        )
                    )
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._log.warning(f"quote poll for {symbol}: {self._scrub(exc)}")
            await asyncio.sleep(self._cfg.poll_seconds)

    async def _poll_bars(self, bar_type: BarType) -> None:
        name, seconds = _timeframe(bar_type)
        symbol = bar_type.instrument_id.symbol.value
        instrument = self._instrument_provider.find(bar_type.instrument_id)
        while True:
            try:
                # Two bars, position 0 being the one still forming: the closed
                # bar is the one behind it, and only that one is published.
                rows = await self._bridge.bars(symbol, name, count=2, start=0)
                for row in rows:
                    opened = int(row.get("time") or 0)
                    if opened <= self._last_bar.get(str(bar_type), 0):
                        continue
                    if _is_forming(opened, seconds, self._clock.timestamp_ns()):
                        continue
                    self._last_bar[str(bar_type)] = opened
                    self._handle_data(_bar(bar_type, row, instrument, seconds))
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._log.warning(f"bar poll for {symbol} {name}: {self._scrub(exc)}")
            await asyncio.sleep(max(1.0, seconds / 10.0))

    # ──── every tick ────
    def _publish_tick(self, instrument_id: Any, instrument: Any, row: dict) -> bool:
        """One bridge tick as a `QuoteTick`, once.

        **Nothing here reads `last`, `volume` or `volume_real`, and nothing
        reads `flags`.** An MT5 tick is a quote update: the trade fields read 0
        or a constant 5000, so there is no trade tick to build. `flags` is a
        bitfield with an undocumented bit 128, and a one-sided revision is
        `flags in (4, 130)` rather than `(2, 4)` - reading it wrongly
        under-reports one-sidedness as 10.0% where the truth is 22.8%. Both
        sides are always published, so no flag is needed to build the quote.
        """
        symbol = instrument_id.symbol.value
        bid, ask = float(row.get("bid") or 0.0), float(row.get("ask") or 0.0)
        msc = _milliseconds(row)
        if bid <= 0 or ask <= 0 or msc is None:
            return False
        mark, seen = self._mark.get(symbol, (0, set()))
        if msc < mark:
            self.stale_ticks += 1
            return False
        if msc == mark and (bid, ask) in seen:
            return False
        self._mark[symbol] = (msc, {(bid, ask)} if msc > mark else seen | {(bid, ask)})
        offset = int(getattr(self._cfg, "server_offset_seconds", 0) or 0)
        ts_event = msc * 1_000_000 - offset * 1_000_000_000
        self._handle_data(
            QuoteTick(
                instrument_id=instrument_id,
                bid_price=Price(bid, instrument.price_precision),
                ask_price=Price(ask, instrument.price_precision),
                bid_size=Quantity(1, 0),
                ask_size=Quantity(1, 0),
                ts_event=ts_event,
                ts_init=max(self._clock.timestamp_ns(), ts_event),
            )
        )
        return True

    async def _catch_up(self, instrument_id: Any, instrument: Any) -> int:
        """Publish every tick since the watermark, from `copy_ticks_range`.

        The range call takes whole seconds, so it re-reads up to a second of
        ticks already published; `_publish_tick` is what drops them.
        """
        symbol = instrument_id.symbol.value
        mark = self._mark.get(symbol, (0, set()))[0]
        now_s = int(self._clock.timestamp_ns() / 1e9)
        rows = await self._bridge.ticks(symbol, mark // 1000 if mark else now_s, now_s + 1)
        rows = sorted(rows, key=lambda r: _milliseconds(r) or 0)
        return sum(self._publish_tick(instrument_id, instrument, r) for r in rows)

    async def _pull_ticks(self, instrument_id: Any) -> None:
        """`quote_source='ticks'`: complete, up to one interval late."""
        symbol = instrument_id.symbol.value
        instrument = self._instrument_provider.find(instrument_id)
        # Start from now: history is `request_*`, not a subscription's job.
        self._mark.setdefault(symbol, (int(self._clock.timestamp_ns() / 1e6), set()))
        while True:
            try:
                await self._catch_up(instrument_id, instrument)
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._log.warning(f"tick pull for {symbol}: {self._scrub(exc)}")
            await asyncio.sleep(self._cfg.poll_seconds)

    async def _stream_quotes(self, instrument_id: Any) -> None:
        """`quote_source='push'`: ticks as the transport delivers them.

        A frame is `{"type": "tick", "symbol", "bid", "ask", "time_msc",
        "flags", "seq"}`. When `seq` is present, a jump means ticks were lost
        between the terminal and here, and the gap is refilled from
        `copy_ticks_range` rather than ignored. A dropped stream is refilled
        the same way before it resumes.
        """
        symbol = instrument_id.symbol.value
        instrument = self._instrument_provider.find(instrument_id)
        self._mark.setdefault(symbol, (int(self._clock.timestamp_ns() / 1e6), set()))
        while True:
            try:
                await self._catch_up(instrument_id, instrument)
                self._seq.pop(symbol, None)
                async for frame in self._bridge.stream([symbol]):
                    kind = frame.get("type")
                    if kind == "error":
                        self._log.warning(
                            f"stream error for {symbol}: {self._scrub(frame.get('message'))}"
                        )
                        continue
                    if kind != "tick" or frame.get("symbol") != symbol:
                        continue
                    seq = frame.get("seq")
                    last = self._seq.get(symbol)
                    if seq is not None:
                        self._seq[symbol] = int(seq)
                        if last is not None and int(seq) != last + 1:
                            self._log.warning(f"{symbol}: stream gap {last} -> {seq}, refilling")
                            await self._catch_up(instrument_id, instrument)
                    self._publish_tick(instrument_id, instrument, frame)
                self._log.warning(f"stream for {symbol} ended")
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._log.warning(f"stream for {symbol}: {self._scrub(exc)}")
            await asyncio.sleep(float(getattr(self._cfg, "reconnect_seconds", 1.0) or 1.0))

    # ──── history, which is the complete side ────
    async def _request_bars(self, request: Any) -> None:
        name, seconds = _timeframe(request.bar_type)
        symbol = request.bar_type.instrument_id.symbol.value
        instrument = self._instrument_provider.find(request.bar_type.instrument_id)
        rows = await self._bridge.bars(symbol, name, count=int(request.limit or 1000), start=1)
        bars = [_bar(request.bar_type, row, instrument, seconds) for row in rows if row.get("time")]
        bars.sort(key=lambda b: b.ts_event)
        # **By keyword.** The first version passed `(bar_type, bars, last_bar,
        # id, params)` against a signature of `(bar_type, bars, correlation_id,
        # start, end, params)`: five arguments for six, and the last bar where
        # the correlation id belongs. A history request raised `TypeError`.
        self._handle_bars(
            bar_type=request.bar_type,
            bars=bars,
            correlation_id=request.id,
            start=request.start,
            end=request.end,
            params=request.params,
        )


def _timeframe(bar_type: BarType) -> tuple[str, float]:
    spec = str(bar_type.spec)
    for key, (name, seconds) in TIMEFRAMES.items():
        if spec.startswith(key):
            return name, seconds
    raise ValueError(f"{bar_type} has no MT5 timeframe - this venue serves {sorted(TIMEFRAMES)}")


def _is_forming(opened: int, seconds: float, now_ns: int) -> bool:
    """Has this bar's window closed yet?

    A forming bar is a different measurement, not an early one: the sampling
    variance of `log(garman_klass)` runs 0.265 on a bar built from thousands of
    ticks and 0.50 on one built from twelve, and the bias goes from -0.15 to
    -0.79. A tenth-formed bar is an accurate reading of a tenth of the bar.
    """
    return (now_ns / 1e9) < (opened + seconds)


def _bar(bar_type: BarType, row: dict, instrument: Any, seconds: float) -> Bar:
    """One bridge row as a Nautilus bar, with the timestamp moved to its close."""
    opened = float(row.get("time") or 0.0)
    closes = secs_to_nanos(opened + seconds)
    digits = instrument.price_precision
    size = instrument.size_precision
    return Bar(
        bar_type=bar_type,
        open=Price(float(row["open"]), digits),
        high=Price(float(row["high"]), digits),
        low=Price(float(row["low"]), digits),
        close=Price(float(row["close"]), digits),
        volume=Quantity(float(row.get("tick_volume") or row.get("real_volume") or 0.0), size),
        ts_event=closes,
        ts_init=closes,
    )
